export interface RubricaDesarrollada {
  codigo: string;
  nombre: string;
  objetivo: string;
  tipo: string;
  criterio: string;
  indicadores: string[];
  ponderacion: string;
  ejemplo: string;
  L4: string;
  L3: string;
  L2: string;
  L1: string;
}

export interface UDData {
  id: string;
  titulo: string;
  evidencia: string;
  rubricas: RubricaDesarrollada[];
}

export interface BloqueData {
  id: string;
  nombre: string;
  curso: string;
  uds: UDData[];
}

export interface MaestraRubric {
  id: string;
  nombre: string;
  L4: string;
  L3: string;
  L2: string;
  L1: string;
}

