// ============================================================
// HELPER: genera rúbrica desarrollada a partir de datos cortos
// ============================================================
function r(
  codigo: string, nombre: string, objetivo: string, tipo: string, criterio: string,
  indicadores: string[], ponderacion: string, ejemplo: string,
  L4: string, L3: string, L2: string, L1: string
): RubricaDesarrollada {
  return { codigo, nombre, objetivo, tipo, criterio, indicadores, ponderacion, ejemplo, L4, L3, L2, L1 };
}

